#!/usr/bin/env node
// Generate the build-time constants from the single source of truth, config/veloxfetch.yaml.
//
//   node scripts/gen-config.mjs            write the generated files
//   node scripts/gen-config.mjs --check    verify the generated files and the install scripts are in step
//                                          with the YAML; exit non-zero (naming what drifted) if not
//
// The generated values are compiled into the signed binary and the installers; the app never reads the
// YAML at run time (see config/veloxfetch.yaml for why). tests/security/config.test.mjs runs --check.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = "config/veloxfetch.yaml";

// A deliberately tiny parser for this one flat file: `key: value` lines, `#` comments, optional quotes.
// Not a general YAML parser (and not used at run time), so there is no dependency to audit.
function parseConfig(text) {
  const out = {};
  text.split(/\r?\n/).forEach((raw, i) => {
    const line = raw.replace(/\s+#.*$/, "").trimEnd();
    if (!line || line.trimStart().startsWith("#")) return;
    const m = /^([a-z_]+):\s*(.*)$/.exec(line);
    if (!m) throw new Error(`${SOURCE}:${i + 1}: not a "key: value" line: ${raw}`);
    out[m[1]] = m[2].replace(/^["']|["']$/g, "").trim();
  });
  return out;
}

// Everything derived from the source, in one place.
function values(cfg) {
  for (const k of ["product", "releases_owner", "releases_repo", "chrome_extension_id", "firefox_extension_id", "native_host_name", "chrome_store_update_url"]) {
    if (!cfg[k]) throw new Error(`${SOURCE}: missing "${k}"`);
  }
  const repo = `https://github.com/${cfg.releases_owner}/${cfg.releases_repo}`;
  return {
    product: cfg.product,
    releasePage: `${repo}/releases`,
    updateFeed: `${repo}/releases/latest/download/latest.json`,
    updatePackages: `${repo}/releases/download/`,
    chromeExtensionId: cfg.chrome_extension_id,
    chromeStoreId: cfg.chrome_store_id || "",
    firefoxExtensionId: cfg.firefox_extension_id,
    hostName: cfg.native_host_name,
    chromeStoreUpdateUrl: cfg.chrome_store_update_url,
  };
}

const RUST_HEAD = "// @generated by scripts/gen-config.mjs from config/veloxfetch.yaml — do not edit by hand.\n\n";
const rustStr = (s) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
const rustOpt = (s) => (s ? `Some(${rustStr(s)})` : "None");

// The generated files, each keyed by its path in the repo.
function artifacts(v) {
  return {
    "crates/browser-bridge/src/generated/identity.rs":
      RUST_HEAD +
      "/// Chromium extension id, fixed by the public key in the extension's manifest.\n" +
      `pub const CHROME_EXTENSION_ID: &str = ${rustStr(v.chromeExtensionId)};\n` +
      "/// The extension's id in the Chrome Web Store (`None` = not published; Developer mode only).\n" +
      `pub const CHROME_STORE_ID: Option<&str> = ${rustOpt(v.chromeStoreId)};\n` +
      "/// Firefox add-on id (`browser_specific_settings.gecko.id`).\n" +
      `pub const FIREFOX_EXTENSION_ID: &str = ${rustStr(v.firefoxExtensionId)};\n` +
      "/// Name the host is registered under with the browsers.\n" +
      `pub const HOST_NAME: &str = ${rustStr(v.hostName)};\n`,

    "crates/system-integration/src/generated/identity.rs":
      RUST_HEAD +
      "/// Chrome Web Store's update service: what the browser contacts to fetch the published extension.\n" +
      `pub const CHROME_STORE_UPDATE_URL: &str = ${rustStr(v.chromeStoreUpdateUrl)};\n`,

    "apps/desktop/src-tauri/src/generated/identity.rs":
      RUST_HEAD +
      "/// The product name.\n" +
      `pub const PRODUCT: &str = ${rustStr(v.product)};\n` +
      "/// The public download repository's release page.\n" +
      `pub const RELEASE_PAGE: &str = ${rustStr(v.releasePage)};\n` +
      "/// GitHub's \"latest release\" feed (drafts and pre-releases are never served here).\n" +
      `pub const UPDATE_FEED: &str = ${rustStr(v.updateFeed)};\n` +
      "/// The prefix every update package address must start with.\n" +
      `pub const UPDATE_PACKAGES: &str = ${rustStr(v.updatePackages)};\n`,
  };
}

// The install scripts and the NSIS hook carry the value literally and we verify it here against the YAML: the
// shell scripts run on the user's machine (where this repo is absent), and the Tauri NSIS bundler compiles the
// hook in its own scaffold folder, so neither can safely pull in a generated file. A mismatch names the file.
function scriptChecks(v) {
  return [
    { file: "apps/desktop/src-tauri/packaging/postinst.sh", must: [`VELOX_EXTENSION_ID=${v.chromeStoreId}`, `"external_update_url":"${v.chromeStoreUpdateUrl}"`] },
    { file: "apps/desktop/src-tauri/packaging/postrm.sh", must: [`VELOX_EXTENSION_ID=${v.chromeStoreId}`] },
    { file: "apps/desktop/src-tauri/installer-hooks.nsh", must: [`!define VELOX_EXTENSION_ID "${v.chromeStoreId}"`, `!define VELOX_STORE_UPDATE_URL "${v.chromeStoreUpdateUrl}"`] },
  ];
}

const check = process.argv.includes("--check");
const v = values(parseConfig(fs.readFileSync(path.join(ROOT, SOURCE), "utf8")));
const arts = artifacts(v);
const drift = [];

for (const [rel, want] of Object.entries(arts)) {
  const abs = path.join(ROOT, rel);
  if (check) {
    const got = fs.existsSync(abs) ? fs.readFileSync(abs, "utf8") : null;
    if (got !== want) drift.push(`${rel} is out of date with ${SOURCE}`);
  } else {
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, want);
    console.log(`wrote ${rel}`);
  }
}

if (check) {
  for (const { file, must } of scriptChecks(v)) {
    const body = fs.readFileSync(path.join(ROOT, file), "utf8");
    for (const s of must) if (!body.includes(s)) drift.push(`${file} must contain \`${s}\` (from ${SOURCE})`);
  }
  if (drift.length) {
    console.error("config out of step with the single source of truth:\n  - " + drift.join("\n  - ") + "\n\nrun: node scripts/gen-config.mjs   (and update the install scripts it names)");
    process.exit(1);
  }
  console.log(`config in step with ${SOURCE}`);
} else {
  console.log(`\nInstall scripts carry the value literally (they run where this repo is absent); keep them in step:`);
  for (const { file, must } of scriptChecks(v)) console.log(`  ${file}: ${must.join(" , ")}`);
}
